                method: .get,
                path: "/struttura-service-v1/sedi/\(RestRequest.pathSegment(siteId))"
            ),
            roles: [.any]
        )
    }

    /// - Parameters:
    ///   - facultyCode: codice della struttura didattica
    ///   - facultyDescription: descrizione della struttura didattica (se viene utilizzato il carattere * viene applicato il like)
    ///   - siteType: definisce il tipo di struttura (FAC facolt�, DIP dipartimento)
    ///   - activeInAcademicYear: filtra le strutture attive nell'anno accademico indicato
    ///   - courseOfStudyCode: codice del corso di studio
    ///   - order: consente di specificare un ordine per il recupero dei record. La sintassi è la seguente * +/- : specifica l'ordinamento (+ = ASC, - = DESC); se omesso viene utilizzato + * field : nome del campo da ordinare E' possibile indicare più campi separandoli da virgola (Es: +annoCorso,+adCod)
    ///   - optionalFields: specifica la lista dei campi opzionali (che non vengono recupeati di default); impostando il valore `ALL` vengono mostrati tutti i campi. Per gli oggetti è possibile utilizzare la notazione *Ant Glob Patterns* I dettagli sono presenti [qui](https://wiki.u-gov.it/confluence/display/ESSE3/Servizi+REST+su+ESSE3#ServiziRESTsuESSE3-Filtrosuicampidelleclassidimodello) Esempi * per il campo childObj con la poprietà childProp utilizzare la notazione `childProp.prop1` * Per visualizzare tutte le proprietà di childObj utilizzare la notazione `childProp.*` * Per visualizzare tutte le proprietà di childObj e di tutti i discendenti utilizzare la notazione `childProp.**`
    ///   - fields: specifica la lista dei campi opzionali (che non vengono recupeati di default); impostando il valore `ALL` vengono mostrati tutti i campi. Per gli oggetti è possibile utilizzare la notazione *Ant Glob Patterns* I dettagli sono presenti [qui](https://wiki.u-gov.it/confluence/display/ESSE3/Servizi+REST+su+ESSE3#ServiziRESTsuESSE3-Filtrosuicampidelleclassidimodello) Esempi * per il campo childObj con la poprietà childProp utilizzare la notazione `childProp.prop1` * Per visualizzare tutte le proprietà di childObj utilizzare la notazione `childProp.*` * Per visualizzare tutte le proprietà di childObj e di tutti i discendenti utilizzare la notazione `childProp.**`
    ///   - filter: il parametro consente di applicare dei filtri alla classe di modello utilizzando il linguaggio  [RSQL](https://github.com/jirutka/rsql-parser). La lista degli operatori utilizzabili è disponibile [qui](https://wiki.u-gov.it/confluence/display/ESSE3/Servizi+REST+su+ESSE3#ServiziRESTsuESSE3-Filtrosullerigherecuperate) *NB* il filtro viene applicato DOPO aver recuperato i dati
    public func getDidacticStructures(
        facultyCode: String? = nil,
        facultyDescription: String? = nil,
        siteType: String? = nil,
        activeInAcademicYear: Int? = nil,
        courseOfStudyCode: String? = nil,
        order: String? = nil,
        optionalFields: String? = nil,
        fields: String? = nil,
        filter: String? = nil
    ) async throws -> [Esse3StructureWithLocations] {
        try await client.jsonList(
            RestRequest(
                method: .get,
                path: "/struttura-service-v1/strutture",
                query: [
                    ("facCod", facultyCode),
                    ("facDes", facultyDescription),
                    ("sdrTip", siteType),
                    ("attivoInAa", activeInAcademicYear),
                    ("cdsCod", courseOfStudyCode),
                    ("order", order),
                    ("optionalFields", optionalFields),
                    ("fields", fields),
                    ("filter", filter)
                ]
            ),
            roles: [.any]
        )
    }

    /// - Parameters:
    ///   - facultyId: ID della struttura didattica
    ///   - optionalFields: specifica la lista dei campi opzionali (che non vengono recupeati di default); impostando il valore `ALL` vengono mostrati tutti i campi. Per gli oggetti è possibile utilizzare la notazione *Ant Glob Patterns* I dettagli sono presenti [qui](https://wiki.u-gov.it/confluence/display/ESSE3/Servizi+REST+su+ESSE3#ServiziRESTsuESSE3-Filtrosuicampidelleclassidimodello) Esempi * per il campo childObj con la poprietà childProp utilizzare la notazione `childProp.prop1` * Per visualizzare tutte le proprietà di childObj utilizzare la notazione `childProp.*` * Per visualizzare tutte le proprietà di childObj e di tutti i discendenti utilizzare la notazione `childProp.**`
    public func getDidacticStructure(
        facultyId: Int64,
        optionalFields: String? = nil
    ) async throws -> Esse3StructureWithLocations {
        try await client.json(
            RestRequest(
                method: .get,
                path: "/struttura-service-v1/strutture/\(RestRequest.pathSegment(facultyId))/",
                query: [("optionalFields", optionalFields)]
            ),
            roles: [.any]
        )
    }

    /// - Parameters:
    ///   - courseTypeCode: codice del tipo di corso di studio
    ///   - courseTypeDescription: descrizione del tipo di corso di studio (se viene utilizzato il carattere * viene applicato il like)
    ///   - facultyId: ID della struttura didattica
    ///   - phdFlag: Indica se il tipo corso rappresenta un Dottorato di Ricerca, ossia un titolo accademico italiano post lauream, corrispondente al 3° ciclo dell'istruzione superiore in molti paesi del mondo. È stato introdotto nel sistema universitario italiano nel 1980 e rappresenta il più alto grado di istruzione universitaria, come dettato dal Processo di Bologna.
    ///   - specializationSchoolFlag: Indica se il tipo corso rappresenta una scuola di specializzazione, ossia un titolo accademico italiano post lauream a carattere professionalizzante, che ha l’obiettivo di fornire conoscenze e abilità per lo svolgimento di funzioni altamente qualificate, richieste per l’esercizio di particolari attività professionali, esclusivamente in applicazione di direttive europee o di specifiche norme di legge.
    ///   - tcGroupCode: codice codice raggruppamento tipi corso
    ///   - order: consente di specificare un ordine per il recupero dei record. La sintassi è la seguente * +/- : specifica l'ordinamento (+ = ASC, - = DESC); se omesso viene utilizzato + * field : nome del campo da ordinare E' possibile indicare più campi separandoli da virgola (Es: +annoCorso,+adCod)
    public func getCourseTypes(
        courseTypeCode: String? = nil,
        courseTypeDescription: String? = nil,
        facultyId: Int? = nil,
        phdFlag: Int? = nil,
        specializationSchoolFlag: Int? = nil,
        tcGroupCode: String? = nil,
        order: String? = nil
    ) async throws -> [Esse3CourseTypes] {
        try await client.jsonList(
            RestRequest(
                method: .get,
                path: "/struttura-service-v1/tipiCorso",
                query: [
                    ("tipoCorsoCod", courseTypeCode),
                    ("tipoCorsoDes", courseTypeDescription),
                    ("facId", facultyId),
                    ("dottoratoFlg", phdFlag),
                    ("scuolaSpecFlg", specializationSchoolFlag),
                    ("gruppoTcCod", tcGroupCode),
                    ("order", order)
                ]
            ),
            roles: [.any]
        )
    }
